window.DEX_DATA["sources:backport-80e928f404330521"]={"json":{"skins":[{"filename":"preschooler_f1.png"}],"names":[{"name":"塞尔达"},{"name":"蕾妮"},{"name":"盖比"},{"name":"小舞步"},{"name":"小珍妮"}],"chat":[{"lines":[{"text":"听说数学和写字特别无聊，我只想学宝可梦的知识！"},{"text":"真想快点到十岁，这样就不用上学啦！"}]},{"lines":[{"text":"班里有个男孩总问我喜不喜欢水跃鱼。"},{"text":"不喜欢！我觉得它们脏兮兮的！"}]},{"lines":[{"text":"妈妈喜欢卡拉卡拉，爸爸喜欢小火龙。"},{"text":"我觉得它们看起来差不多……"}]},{"lines":[{"text":"妈妈在生日时送了我一只伊布！"},{"text":"回家后，我要拿爸爸的叶之石给它用！"}]}]}};
